 Future<void> toggle(bool value)async{setState(()=>busy=true);try{double? lat,lon;if(value){var permission=await Geolocator.checkPermission();if(permission==LocationPermission.denied)permission=await Geolocator.requestPermission();if(permission==LocationPermission.denied||permission==LocationPermission.deniedForever)throw ApiFailure('Location permission is required to go online.');final pos=await Geolocator.getCurrentPosition(locationSettings:const LocationSettings(accuracy:LocationAccuracy.high,timeLimit:Duration(seconds:15)));lat=pos.latitude;lon=pos.longitude;}await widget.api.call('PATCH','/mechanic/availability',data:{'online':value,if(lat!=null)'latitude':lat,if(lon!=null)'longitude':lon});await refresh();}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
