class MechanicJob extends StatefulWidget {const MechanicJob({super.key,required this.api,required this.id});final BikeApi api;final String id;@override State<MechanicJob> createState()=>_MechanicJobState();}
class _MechanicJobState extends State<MechanicJob>{Map<String,dynamic>? job;String? error;bool busy=false;@override void initState(){super.initState();refresh();}Future<void> refresh()async{try{final r=await widget.api.call('GET','/rescues/${widget.id}');if(mounted)setState((){job=Map<String,dynamic>.from(r);error=null;});}catch(e){if(mounted)setState(()=>error=e.toString());}}
